BEGIN READ ONLY;SET LOCAL statement_timeout='10s';SELECT jsonb_build_object('role',current_user,'database',current_database(),'readOnly',current_setting('transaction_read_only'),'ownerMembers',(SELECT coalesce(jsonb_agg(jsonb_build_object('role',r.rolname,'superuser',r.rolsuper,'inherit',r.rolinherit)),'[]'::jsonb) FROM pg_roles r WHERE r.rolname<>current_user AND pg_has_role(r.oid,current_user::regrole,'MEMBER'))) metadata;ROLLBACK;